std::array<LiftedPoint, 4> lifted_vertices;
for (int i = 0; i < 4; ++i) {
    auto v = c->vertex(i)->point();
    double w = c->vertex(i)->info();
    lifted_vertices[i] = lifted_point(v.x(), v.y(), v.z(), w);
}

// Compute the hyperplane equation in 4D
HyperPlane hp(lifted_vertices[0], lifted_vertices[1],
              lifted_vertices[2], lifted_vertices[3]);

// Get the coefficients of the hyperplane equation: a*x + b*y + c*z + d*w + e = 0
auto coeffs = hp.coefficients();
double a = coeffs[0];
double b = coeffs[1];
double c = coeffs[2];
double d = coeffs[3];
double e = coeffs[4];

// The velocity is the negative gradient of the potential in 3D space
// From the hyperplane equation, we have w = (-a*x - b*y - c*z - e)/d
// The potential Φ = w/(2*time), so the velocity v = -∇Φ = (a,b,c)/(2*d*time)
double factor = 1.0 / (2.0 * d * time);
return Vector(a * factor, b * factor, c * factor);

